package com.fran.tv;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
import androidx.media3.common.*;import androidx.media3.exoplayer.*;import androidx.media3.exoplayer.source.*;import androidx.media3.datasource.*;import androidx.media3.ui.*;
import java.util.*;

@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public class PlayerActivity extends Activity {
 Ui u;FrameLayout root;PlayerView video;ExoPlayer player;LinearLayout panel,rows,info,errorBox;TextView detail,message,categoryButton;ScrollView listScroll;
 List<Channel> all=new ArrayList<>(),active=new ArrayList<>();Channel current;String group="Todos",digits="";boolean panelOpen=false,started=false;int retries=0,aspect=0;long lastOk=0;Handler h=new Handler(Looper.getMainLooper());
 Runnable reconnect,watchdog,stable,hideInfo;final Runnable singleOk=()->{lastOk=0;openPanel();};final Runnable numeric=()->jumpNumber();
 @Override public void onCreate(Bundle b){super.onCreate(b);u=new Ui(this);u.immersive();getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);all=Catalog.load(this);ArrayList<String> ids=getIntent().getStringArrayListExtra("ids");for(Channel c:all)if(ids==null||ids.contains(c.id))active.add(c);if(active.isEmpty())active.addAll(all);group=getIntent().getStringExtra("category");if(group==null||group.equals("Buscar"))group="Todos";String id=getIntent().getStringExtra("channel");for(Channel c:all)if(c.id.equals(id))current=c;if(current==null&&!active.isEmpty())current=active.get(0);build();}
 void build(){root=new FrameLayout(this);root.setBackgroundColor(Color.BLACK);setContentView(root);video=new PlayerView(this);video.setUseController(false);video.setKeepScreenOn(true);root.addView(video,new FrameLayout.LayoutParams(-1,-1));
  info=u.column();info.setPadding(u.d(20),u.d(14),u.d(20),u.d(14));info.setBackground(u.bg(0xe6091726,12,0xff284252));detail=u.text("",20,Ui.WHITE,true);info.addView(detail);u.gap(info,7);info.addView(u.text("↑↓ Canal    OK Menú    Doble OK Favorito    Atrás Volver",11,Ui.MUTED,false));FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(u.d(500),-2,Gravity.BOTTOM|Gravity.END);ip.setMargins(0,0,u.d(24),u.d(24));root.addView(info,ip);
  errorBox=u.column();errorBox.setGravity(Gravity.CENTER);errorBox.setPadding(u.d(25),u.d(20),u.d(25),u.d(20));errorBox.setBackground(u.bg(0xec071321,16,0xff24445b));message=u.text("Conectando…",17,Ui.WHITE,true);message.setGravity(Gravity.CENTER);errorBox.addView(message);LinearLayout actions=u.row();u.gap(errorBox,14);TextView retry=u.button("Reintentar",()->{retries=0;play();});TextView channels=u.button("Ver canales",()->openPanel());actions.addView(retry,u.lp(130,36));actions.addView(channels,u.lp(130,36));errorBox.addView(actions);actions.setVisibility(View.GONE);FrameLayout.LayoutParams ep=new FrameLayout.LayoutParams(u.d(420),-2,Gravity.CENTER);root.addView(errorBox,ep);
  panel=u.column();panel.setPadding(u.d(22),u.d(20),u.d(18),u.d(18));panel.setBackground(new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{0xfc061321,0xf2091c2d}));FrameLayout.LayoutParams pp=new FrameLayout.LayoutParams(u.d(345),-1,Gravity.START);root.addView(panel,pp);LinearLayout brand=u.row();brand.addView(u.brand(36));brand.addView(u.text("FranTV",25,Ui.WHITE,true));panel.addView(brand,u.lp(-1,42));u.gap(panel,14);panel.addView(u.text("Canales",29,Ui.WHITE,true));u.gap(panel,12);categoryButton=u.button(group+"  ▾",()->chooseCategory());panel.addView(categoryButton,u.lp(-1,38));u.gap(panel,10);
  listScroll=new ScrollView(this);listScroll.setClipToPadding(true);listScroll.setClipChildren(true);listScroll.setVerticalScrollBarEnabled(false);rows=u.column();rows.setPadding(u.d(3),u.d(4),u.d(3),u.d(8));listScroll.addView(rows);panel.addView(listScroll,new LinearLayout.LayoutParams(-1,0,1));TextView aspectButton=u.button("Imagen: Ajustar",()->{});aspectButton.setOnClickListener(v->{aspect=(aspect+1)%3;video.setResizeMode(aspect==0?AspectRatioFrameLayout.RESIZE_MODE_FIT:aspect==1?AspectRatioFrameLayout.RESIZE_MODE_ZOOM:AspectRatioFrameLayout.RESIZE_MODE_FILL);aspectButton.setText("Imagen: "+new String[]{"Ajustar","Ampliar","Llenar"}[aspect]);});panel.addView(aspectButton,u.lp(-1,32));u.gap(panel,8);panel.addView(u.text("OK Ver  ·  Mantén OK Favorito\nAtrás Cerrar menú",11,Ui.MUTED,false));panel.setVisibility(View.GONE);
 }
 @Override protected void onStart(){super.onStart();started=true;DefaultHttpDataSource.Factory http=new DefaultHttpDataSource.Factory().setUserAgent("FranTV/1.0").setAllowCrossProtocolRedirects(true).setConnectTimeoutMs(10000).setReadTimeoutMs(15000);DefaultDataSource.Factory data=new DefaultDataSource.Factory(this,http);DefaultRenderersFactory renderers=new DefaultRenderersFactory(this).setEnableDecoderFallback(true);
  player=new ExoPlayer.Builder(this,renderers).setMediaSourceFactory(new DefaultMediaSourceFactory(data)).setLoadControl(new DefaultLoadControl.Builder().setBufferDurationsMs(15000,45000,1500,3000).build()).build();video.setPlayer(player);player.setAudioAttributes(new AudioAttributes.Builder().setUsage(C.USAGE_MEDIA).setContentType(C.AUDIO_CONTENT_TYPE_MOVIE).build(),true);player.setHandleAudioBecomingNoisy(true);
  player.addListener(new Player.Listener(){@Override public void onPlayerError(PlaybackException e){if(started)scheduleRetry();}@Override public void onPlaybackStateChanged(int state){if(!started)return;if(state==Player.STATE_READY){errorBox.setVisibility(View.GONE);if(watchdog!=null)h.removeCallbacks(watchdog);}else if(state==Player.STATE_BUFFERING){showMessage("Cargando señal…",false);armWatchdog();}else if(state==Player.STATE_ENDED){scheduleRetry();}}@Override public void onIsPlayingChanged(boolean playing){if(stable!=null)h.removeCallbacks(stable);if(playing){stable=()->retries=0;h.postDelayed(stable,15000);}}});play();}
 void play(){if(!started||player==null)return;if(current==null){showMessage("No hay canales disponibles.",true);return;}cancelRetry();Catalog.prefs(this).edit().putString("lastChannel",current.id).apply();MediaItem.Builder item=new MediaItem.Builder().setUri(current.url).setMediaId(current.id);if(current.url.toLowerCase(Locale.ROOT).contains(".m3u8"))item.setMimeType(MimeTypes.APPLICATION_M3U8);else if(current.url.toLowerCase(Locale.ROOT).contains(".mpd"))item.setMimeType(MimeTypes.APPLICATION_MPD);player.setMediaItem(item.build());player.prepare();player.play();showMessage(retries>0?"Reconectando… "+retries+" de 4":"Conectando con "+current.name+"…",false);showInfo();armWatchdog();}
 void cancelRetry(){if(reconnect!=null)h.removeCallbacks(reconnect);if(watchdog!=null)h.removeCallbacks(watchdog);if(stable!=null)h.removeCallbacks(stable);}
 void armWatchdog(){if(watchdog!=null)h.removeCallbacks(watchdog);watchdog=()->{if(started&&player!=null&&player.getPlaybackState()!=Player.STATE_READY)scheduleRetry();};h.postDelayed(watchdog,22000);}
 void scheduleRetry(){if(!started)return;cancelRetry();if(retries>=4){if(player!=null)player.stop();showMessage("Esta señal no está disponible ahora.\nPuedes reintentar o elegir otro canal.",true);return;}retries++;showMessage("La señal se interrumpió. Reconectando… "+retries+" de 4",false);reconnect=()->play();h.postDelayed(reconnect,Math.min(8000,1000L*(1<<retries)));}
 void showMessage(String s,boolean actions){message.setText(s);errorBox.setVisibility(View.VISIBLE);errorBox.getChildAt(2).setVisibility(actions?View.VISIBLE:View.GONE);if(actions&&!panelOpen)((LinearLayout)errorBox.getChildAt(2)).getChildAt(0).requestFocus();}
 void showInfo(){if(current==null)return;detail.setText((Catalog.favorite(this,current)?"★  ":"")+current.numberText()+" · "+current.name+"\n"+current.category);info.setVisibility(View.VISIBLE);if(hideInfo!=null)h.removeCallbacks(hideInfo);hideInfo=()->{if(!panelOpen)info.setVisibility(View.GONE);};h.postDelayed(hideInfo,4500);}
 void chooseCategory(){LinkedHashSet<String> cats=new LinkedHashSet<>();cats.add("Todos");cats.add("Favoritos");for(Channel c:all)cats.add(c.category);String[] opts=cats.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Elige una categoría").setItems(opts,(d,w)->{group=opts[w];categoryButton.setText(group+"  ▾");renderRows();}).setNegativeButton("Volver",null).show();}
 void renderRows(){rows.removeAllViews();List<Channel> list=Catalog.filter(this,all,group,"");for(Channel c:list){LinearLayout row=u.row();row.setPadding(u.d(10),u.d(5),u.d(10),u.d(5));u.focus(row,current!=null&&c.id.equals(current.id));row.setTag(c.id);TextView number=u.text(c.numberText(),12,Ui.CYAN,true);row.addView(number,u.lp(30,-2));ImageView logo=new ImageView(this);u.logo(logo,c);row.addView(logo,u.lp(45,30));TextView name=u.text("  "+c.name,13,Ui.WHITE,true);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.END);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));row.addView(u.text(Catalog.favorite(this,c)?"★":"☆",17,Ui.CYAN,false));row.setOnClickListener(v->{active=new ArrayList<>(list);current=c;retries=0;play();closePanel();});row.setOnLongClickListener(v->{toggle(c);renderRows();View target=rows.findViewWithTag(c.id);if(target!=null)target.requestFocus();return true;});LinearLayout.LayoutParams p=u.lp(-1,50);p.bottomMargin=u.d(7);rows.addView(row,p);}if(list.isEmpty())rows.addView(u.text("Aún no hay favoritos.\nMantén OK sobre un canal para añadirlo.",15,Ui.MUTED,false));}
 void openPanel(){if(isFinishing())return;panelOpen=true;renderRows();panel.setVisibility(View.VISIBLE);panel.setTranslationX(-u.d(35));panel.setAlpha(0);panel.animate().translationX(0).alpha(1).setDuration(180).start();info.setVisibility(View.GONE);View focus=current==null?null:rows.findViewWithTag(current.id);if(focus!=null)focus.requestFocus();else categoryButton.requestFocus();}
 void closePanel(){panelOpen=false;panel.setVisibility(View.GONE);video.requestFocus();showInfo();}
 void toggle(Channel c){boolean yes=Catalog.toggle(this,c);Toast.makeText(this,yes?"Añadido a favoritos":"Quitado de favoritos",Toast.LENGTH_SHORT).show();showInfo();}
 void step(int delta){if(active.isEmpty())return;int index=0;for(int i=0;i<active.size();i++)if(current!=null&&active.get(i).id.equals(current.id))index=i;current=active.get((index+delta+active.size())%active.size());retries=0;play();}
 void jumpNumber(){String n=digits.replaceFirst("^0+(?!$)","");digits="";for(Channel c:all)if(Integer.toString(c.number).equals(n)){active=new ArrayList<>(all);group="Todos";categoryButton.setText("Todos  ▾");current=c;retries=0;play();return;}Toast.makeText(this,"No existe ese número de canal",Toast.LENGTH_SHORT).show();showInfo();}
 @Override public boolean dispatchKeyEvent(KeyEvent e){int k=e.getKeyCode();if(k==KeyEvent.KEYCODE_BACK||k==KeyEvent.KEYCODE_ESCAPE){if(e.getAction()==KeyEvent.ACTION_UP){if(panelOpen)closePanel();else finish();}return true;}
  if(!panelOpen){if(k>=KeyEvent.KEYCODE_0&&k<=KeyEvent.KEYCODE_9){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){digits+=(k-KeyEvent.KEYCODE_0);if(digits.length()>3)digits=digits.substring(digits.length()-3);detail.setText("Canal "+digits);info.setVisibility(View.VISIBLE);h.removeCallbacks(numeric);h.postDelayed(numeric,1300);}return true;}
   if(k==KeyEvent.KEYCODE_DPAD_UP||k==KeyEvent.KEYCODE_CHANNEL_UP||k==KeyEvent.KEYCODE_DPAD_DOWN||k==KeyEvent.KEYCODE_CHANNEL_DOWN){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){h.removeCallbacks(singleOk);step(k==KeyEvent.KEYCODE_DPAD_UP||k==KeyEvent.KEYCODE_CHANNEL_UP?1:-1);}return true;}
   if(k==KeyEvent.KEYCODE_MENU||k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)openPanel();return true;}
   boolean errorActions=errorBox.getVisibility()==View.VISIBLE&&errorBox.getChildAt(2).getVisibility()==View.VISIBLE;
   if(!errorActions&&(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER)){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){long now=SystemClock.uptimeMillis();if(lastOk!=0&&now-lastOk<350){h.removeCallbacks(singleOk);lastOk=0;if(current!=null)toggle(current);}else{lastOk=now;h.postDelayed(singleOk,350);}}return true;}
  }return super.dispatchKeyEvent(e);}
 @Override protected void onResume(){super.onResume();u.immersive();}
 @Override protected void onStop(){started=false;h.removeCallbacksAndMessages(null);if(player!=null){video.setPlayer(null);player.release();player=null;}super.onStop();}
 @Override protected void onDestroy(){h.removeCallbacksAndMessages(null);super.onDestroy();}
}
